// UUID version 7 (RFC 9562): 48-bit Unix time in milliseconds, then random bits. Ids generated by
// the client sort by creation time, which keeps SQLite and Postgres indexes compact.

const HEX = Array.from({ length: 256 }, (_, byte) => byte.toString(16).padStart(2, '0'));

/**
 * A UUID v7 from a time and 10 random bytes (the caller provides them: expo-crypto on the phone,
 * node:crypto on the server).
 */
export function uuidV7(timeMs: number, random: Uint8Array): string {
  if (!Number.isInteger(timeMs) || timeMs < 0 || timeMs >= 2 ** 48) {
    throw new RangeError(`Invalid time for a UUID v7: ${String(timeMs)}`);
  }
  if (random.length < 10) throw new RangeError('A UUID v7 needs 10 random bytes');

  const bytes = new Uint8Array(16);
  let time = timeMs;
  for (let index = 5; index >= 0; index -= 1) {
    bytes[index] = time % 256;
    time = Math.floor(time / 256);
  }
  bytes.set(random.subarray(0, 10), 6);
  bytes[6] = 0x70 | ((bytes[6] ?? 0) & 0x0f); // version 7
  bytes[8] = 0x80 | ((bytes[8] ?? 0) & 0x3f); // variant 10

  const hex = Array.from(bytes, (byte) => HEX[byte] ?? '00').join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
